(window.TNQ=window.TNQ||[]).push({"terms":{"외현적 수행":{"d":"겉으로 드러나 관찰할 수 있는 행동 수행.","r":[]},"조건 자극":{"d":"처음에는 중립적이었으나 다른 자극과 짝지어져 반응을 일으키게 된 자극.","r":[]},"부적 강화":{"d":"불쾌한 자극을 없애 주어 앞선 행동이 늘어나게 하는 강화.","r":["부적 추동"]},"해결학습":{"d":"공포를 끝내는 활동을 배우는 것으로 장벽 뛰어넘기가 그 예.","r":["부적 강화"]},"소거":{"d":"강화가 중단되어 학습된 반응이 점차 줄어드는 일.","r":["고정비율강화계획"]},"고정비율강화계획":{"d":"정해진 횟수만큼 반응할 때마다 강화를 주는 방식.","r":["소거"]},"인지도":{"d":"환경의 공간적 구조를 머릿속에 그린 지도 같은 표상.","r":[]},"게슈탈트 심리학":{"d":"전체는 부분의 합 이상이라고 보는 심리학 관점.","r":["통찰"]},"통찰":{"d":"문제의 해결 방식을 갑작스럽게 깨닫는 것.","r":["게슈탈트 심리학"]},"비숙련 모델":{"d":"서투른 모습을 보여 관찰자가 성공뿐 아니라 실패에서도 배우게 하는 모델.","r":[]},"부호화":{"d":"정보를 기억에 저장할 수 있는 형태로 바꾸는 일.","r":["표상체계"]},"표상체계":{"d":"정보를 심상이나 언어 같은 형태로 머릿속에 나타내는 체계.","r":["부호화"]},"인지 도식":{"d":"경험을 이해하고 정리하는 데 쓰는 머릿속 틀.","r":["인지구조"]},"인지구조":{"d":"사고를 이루는 머릿속 짜임으로 변화 속에서도 균형을 유지한다.","r":["인지 도식"]},"문화적 도구":{"d":"언어나 상징처럼 문화가 만들어 낸 사고의 수단.","r":["근접발달영역"]},"근접발달영역":{"d":"혼자 하는 수준을 넘어 도움을 받으면 해낼 수 있는 영역.","r":["문화적 도구"]},"선택적 지각":{"d":"감각기억의 많은 정보 중 일부만 골라 받아들이는 지각.","r":["감각기억","단기기억"]},"감각기억":{"d":"외부 자극을 아주 짧게 붙들어 두는 기억의 첫 단계.","r":["단기기억","감각등록기"]},"단기기억":{"d":"감각기억에서 넘어온 정보를 잠시 유지하는 기억으로 장기기억으로 가는 중간 단계.","r":["감각기억","장기기억"]},"장기기억":{"d":"단기기억을 거친 정보가 오래 저장되는 기억.","r":["단기기억"]},"감각등록기":{"d":"외부 정보를 수용해 매우 짧은 기간만 유지하는 기억체계의 요소.","r":["감각기억"]},"재인 기억":{"d":"제시된 것을 보고 전에 접한 것인지 가려내는 기억.","r":["회상 기억"]},"회상 기억":{"d":"단서 없이 저장된 정보를 스스로 떠올리는 기억.","r":["재인 기억"]},"수초화":{"d":"뉴런의 두께가 두꺼워지는 과정으로 정보를 더 빨리 전달하게 한다.","r":[]},"자아실현 욕구":{"d":"모든 인간에게 내재되어 있고 완전히 만족되지 않는 성장 욕구.","r":[]},"통합된 조절":{"d":"내적 조절보다 자율성 정도가 낮은 동기 조절 유형.","r":["내적 조절"]},"내적 조절":{"d":"자율성 정도가 통합된 조절보다 더 높은 동기 조절 유형.","r":["통합된 조절"]},"숙달목표":{"d":"스스로 더 유능해지려는 목표로 학습과 행동을 스스로 조절한다.","r":[]},"추동":{"d":"생리적 결핍이 만드는 긴장 상태로 각 추동은 특정 자극과 연합된다.","r":["부적 추동"]},"부적 추동":{"d":"피로처럼 불쾌해서 벗어나려는 추동 상태.","r":["추동","부적 강화"]},"시청각 교재":{"d":"시각과 청각 자료를 함께 쓰는 교재로 학습효과를 높이는 데 쓰인다.","r":[]}},"notes":{"(satisfying state of affairs)가 따라온다":"만족스러운 사태, 곧 보상이 되는 결과가 반응 뒤에 이어질 때 이 법칙이 작동합니다.","A는 열 살 때 오이를 먹고 몇 시간 뒤 독감에 걸렸다. 그 후 A는 오이를 싫어하게 되었다":"오이를 먹은 뒤 몸이 아팠던 경험이 오이와 연결되어 오이를 싫어하게 된 미각혐오 사례입니다.","‘전체는 부분의 합 이상’ 이라는 게슈탈트 심리학에 근거한다":"통찰학습은 전체가 부분의 합 이상이라는 게슈탈트 심리학을 바탕으로 합니다.","각 추동은 특정 자극과 연합된다":"허기나 갈증 같은 추동마다 그것을 줄여 주는 특정 자극이 짝지어집니다.","감각기억은 선택적 지각에 의해 단기기억으로 처리된다":"감각기억의 많은 정보 중 선택적 지각으로 골라낸 것만 단기기억으로 넘어갑니다.","감각등록기(sensory register)는 매우 짧은 시간동안 많은 정보를 저장한다":"감각등록기는 용량은 크지만 저장되는 시간이 매우 짧습니다.","감각등록기, 단기기억, 그리고 장기기억 간의 체계를 설명한다":"앳킨슨-쉬프린 모형은 기억을 세 요소가 이어지는 체계로 나누어 설명합니다.","강화(reinforcement)는 학습에 필수적이지 않다":"잠재학습에서는 강화가 없어도 학습이 일어날 수 있다고 봅니다.","개가 장벽을 뛰어넘는 것은 공포를 종결시키는 활동을 학습한 것으로 해결학습(solution learning)에 해당된다":"해결학습은 공포를 끝내는 활동을 배운 경우를 가리키며 장벽 넘기가 그 예입니다.","개가 장벽을 뛰어넘는 것은 부적 강화력을 가진다":"장벽을 넘으면 공포가 사라지므로 불쾌한 상태가 제거되는 부적 강화가 작용합니다.","개명한 친구의 새 이름이 기억나지 않고 예전 이름만 떠오르는 것":"이전에 학습한 이름이 새 이름의 회상을 막는 순행간섭의 사례입니다.","계획하기, 평가하기, 점검하기 등이 있다":"메타인지 전략은 자기 학습을 계획하고 점검하고 평가하는 활동으로 이루어집니다.","고전적 조건화와 조작적 조건화라는 두 종류의 학습 경험이 관여한다":"회피학습은 공포가 만들어지는 고전적 조건화와 회피 행동이 유지되는 조작적 조건화가 함께 작용합니다.","과제 도전정도와 학습자 기술수준의 균형이 맞을 때 나타난다":"과제의 어려움과 학습자의 실력이 비슷하게 맞을 때 몰입이 생깁니다.","관찰된 정보를 심상적, 언어적 표상체계로 부호화한다":"본 내용을 이미지나 말의 형태로 바꾸어 기억에 저장하는 과정을 설명합니다.","근접발달영역(ZPD)에서 학습이 이루어진다":"혼자서는 어렵고 도움을 받으면 해낼 수 있는 수준의 영역에서 학습이 일어납니다.","기억은 재인 기억과 회상 기억으로 나눌 수 있다":"보기를 앞에 두고 고르는 재인과 보기 없이 떠올리는 회상으로 기억 인출이 갈립니다.","기억 흔적이 점차 사라지기 때문에 망각이 일어난다":"쇠퇴이론은 시간이 지나며 기억 흔적이 약해져 없어지는 것을 망각의 원인으로 봅니다.","나중에 학습한 정보가 앞서 학습한 정보의 회상을 방해하는 것":"역행간섭은 나중에 배운 것이 이전에 배운 내용을 떠올리지 못하게 하는 현상입니다.","남의 눈에 유능하게 보이는 것에 해당한다":"수행목표는 실제 실력 향상보다 타인에게 유능하게 보이는 것을 겨냥합니다.","내적 조절(intrinsic regulation)의 자율성 정도가 더 높다":"내적 조절은 통합된 조절보다 자율성 정도가 더 높은 조절 유형입니다.","뇌가 경험한 결과들을 재조직하거나 수정하는 능력":"경험의 결과에 따라 뇌가 스스로 재편될 수 있다는 점이 신경가소성의 핵심 성질입니다.","뇌가 신경연결을 재조직하거나 수정하는 능력":"신경가소성은 뇌가 신경 연결을 새로 짜거나 고치는 능력입니다.","뉴런의 두께가 두꺼워지는 과정이며, 수초화가 된 뉴런은 정보를 더 빨리 전달한다":"수초화로 뉴런이 두꺼워지면 신호가 더 빨리 전달됩니다.","단어보다 그림을 더 잘 기억한다":"이중부호화 이론에 따르면 그림은 단어보다 기억에 더 잘 남습니다.","만족되면 다음 단계로 넘어갈 수 있다":"결핍 욕구는 채워지면 다음 단계 욕구로 올라갈 수 있습니다.","멋진 아이돌 가수가 특정 제품을 광고하면, 그 제품에 대한 긍정적 이미지가 형성된다":"호감 가는 가수가 제품과 함께 나오면 가수에 대한 호감이 제품으로 옮겨 가는 연합이 일어납니다.","모델의 행동을 관찰함으로써 학습하는 것이다":"관찰학습은 직접 해 보지 않고 모델이 하는 행동을 보면서 배우는 방식입니다.","문제해결에서 정신적 숙고의 과정을 거치며 미해결에서 해결 상태로의 이행이 갑작스럽다":"통찰은 머릿속 숙고를 거쳐 미해결에서 해결 상태로 갑자기 넘어가는 모습을 보입니다.","물리적 환경에 대한 의존성이 점차 감소하고 인지구조의 활용이 증가하는 것":"내면화는 눈앞의 환경에 덜 기대고 머릿속 인지구조로 처리하는 비중이 커지는 것입니다.","반응 다음에 만족스러운 사상태":"효과의 법칙의 첫째 조건은 반응 뒤에 만족스러운 결과가 이어지는 상황입니다.","발달은 유아기 때 빠르며, 사춘기 이후에도 계속된다":"전두엽은 유아기에 빠르게 자라고 사춘기가 지나도 발달이 이어집니다.","범죄 뉴스에서 특정 국가의 사람을 보면 그 국가 국민에 대한 편견이 형성된다":"뉴스에서 범죄 장면과 특정 국가 사람이 함께 나오면 그 국민에 대한 부정적 연합이 생기는 사례입니다.","보상의 유무는 학습된 결과가 행동으로 나타나는 것에 영향을 미친다":"보상은 학습 자체가 아니라 학습한 것이 행동으로 나타나는지를 좌우합니다.","불빛이 꺼지는 것은 고통에 대한 조건 자극이 된다":"불빛이 꺼지는 것이 고통과 짝지어져 고통을 미리 알리는 신호가 됩니다.","비교적 꾸준한 수행이 나타나며 고정비율강화계획보다 소거에 대한 저항이 크다":"변동비율강화계획은 언제 강화될지 알 수 없어 반응이 꾸준하고 소거가 잘 일어나지 않습니다.","비숙련 모델(unskilled model)은 관찰자에게 모델의 성공뿐만 아니라 실패로부터도 배우게 한다":"비숙련 모델은 실패하는 모습도 보여 주므로 관찰자가 성공과 실패 모두에서 배웁니다.","새로운 정보는 단기기억을 거친 다음에 장기기억으로 이동한다":"새 정보가 장기기억에 닿으려면 먼저 단기기억을 지나야 합니다.","새로운 환경자극을 자신의 인지 도식에 적용시켜 불일치를 해결하는 것":"동화는 새 자극을 이미 가진 도식에 끼워 맞춰 불일치를 푸는 것입니다.","생리적인 욕구는 평형을 유지하려는 욕구이다":"생리적 욕구는 몸의 균형을 지키려는 욕구입니다.","선행과 후속학습 간의 관계적 통찰이 전이를 일으킨다":"형태이조설은 두 학습 사이의 관계를 꿰뚫어 보는 통찰이 전이를 만든다고 봅니다.","선행학습에서 획득한 원리나 법칙을 후속학습에 활용할 수 있다":"일반화설은 앞서 익힌 원리를 뒤의 학습에 가져다 쓰는 것을 전이로 봅니다.","손톱을 깎고 시험을 본 날 성적이 좋았다면 시험을 볼 때마다 손톱을 깎는다":"우연히 겹친 행동과 좋은 결과가 연결돼 실제 인과 없이도 되풀이되는 미신행동입니다.","수행(performance)이 없어도 학습은 일어날 수 있다":"수행은 배운 것을 행동으로 보이는 일이고 학습 자체와는 구별해서 봐야 합니다.","숙달목표 지향적인 사람은 학습과 행동을 스스로 조절한다":"이 유형은 학습 방법과 행동을 자기 힘으로 조율합니다.","스스로 더 유능한 사람이 되려는 것에 해당한다":"숙달목표는 남에게 보이는 것보다 자기 실력을 키우는 데 맞춰져 있습니다.","시청각 교재가 학습효과를 촉진한다":"두 부호를 함께 쓰는 시청각 교재는 학습효과를 높이는 도구로 쓰입니다.","시험이나 과제 수행 시 몹시 긴장하는 일이 많다":"수행목표 지향자는 시험이나 과제를 할 때 긴장이 심한 경우가 많습니다.","실패를 해도 수행에 만족할 수 있다":"실패해도 배움이 있었다면 자신의 수행에 만족할 수 있습니다.","아이가 토끼 옆에 있을 때 갑자기 큰 소리에 노출되면, 토끼에 대한 공포가 형성된다":"토끼가 큰 소리와 짝지어진 탓에 토끼 자체가 공포를 일으키게 되는 조건형성 장면입니다.","알파벳 ‘d’를 배우게 되면서, 앞서 배웠던 ‘b’를 혼동하는 것":"d를 새로 익히면서 앞서 알던 b를 혼동하는 것이 역행간섭 사례입니다.","약물에 의한 일시적 신체 변화는 학습의 범주에 포함되지 않는다":"약을 먹어 잠깐 몸이 달라진 것은 경험의 결과가 아니어서 학습 범주 밖에 있습니다.","약물에 의한 일시적 행동변화":"약물이 잠시 바꿔 놓은 행동은 경험으로 생긴 변화가 아니라서 학습으로 보지 않습니다.","어떤 사건이나 정보를 기억할 때 그 기억에 감정을 결합시키는 역할을 하며 정서와 공격성의 통제를 담당한다":"편도체는 기억에 감정을 덧입히고 정서와 공격성을 조절하는 뇌 부위입니다.","언어나 상징과 같은 문화적 도구의 중요성을 강조한다":"사회문화적 관점은 언어와 상징 같은 도구가 사고를 이끈다고 중시합니다.","언어의 의미를 이해하는 데 중요한 기능을 한다":"베르니케 영역은 언어를 들었을 때 그 의미를 이해하는 데 관여합니다.","연속적인 변화를 겪으면서 일정한 인지구조를 유지하는 과정":"평형화는 변화를 겪는 중에도 인지구조의 균형을 이어 가는 과정입니다.","연습과 훈련을 통해 주의력, 기억력, 판단력을 향상시킬 수 있다":"형식도야설은 훈련으로 마음의 능력을 단련하면 다른 과제에도 효과가 퍼진다고 봅니다.","오류를 실패와 무능으로 여긴다":"틀린 것을 배움의 기회가 아니라 자신의 무능을 드러내는 증거로 받아들입니다.","외부로부터의 정보를 수용하며, 매우 짧은 기간 유지되는 기억체계의 요소이다":"감각등록기는 들어온 정보를 아주 잠깐 붙들어 두는 첫 단계입니다.","외적으로 동기화되어 있어 외적인 강화나 처벌에 민감하다":"보상과 벌 같은 외부 요인에 따라 움직이기 때문에 그것에 민감합니다.","외현적 수행이 없어도 학습은 이루어진다":"외현적 수행은 겉으로 드러난 행동이라서, 드러나지 않아도 학습은 속에서 일어날 수 있습니다.","유기체가 생리적으로 결핍되면 추동 상태를 초래한다":"몸에 필요한 것이 모자라면 그것을 채우려는 긴장 상태, 곧 추동이 생깁니다.","유기체는 욕구가 생길 때 유발되는 학습되지 않은 행동을 가지고 태어난다":"추동감소이론에서는 욕구가 생기면 배우지 않아도 나오는 행동이 타고난다고 봅니다.","의식은 변별적인 정보의 조각이 아닌 전체적이고 연속적인 과정이다":"의식은 낱낱의 정보 조각이 아니라 끊김 없이 이어지는 전체 흐름으로 이해합니다.","의식의 흐름도 경험이 변화하면 함께 변화한다":"의식은 경험과 따로 떨어져 있지 않고 경험이 바뀌면 같이 바뀝니다.","인간 외의 동물들도 관찰을 통해 학습할 수 있다":"관찰학습은 사람만의 능력이 아니고 다른 동물에게서도 나타납니다.","인간은 모델이 매력적이고 유명한 사람일 때 더 잘 배우는 경향이 있다":"모델이 매력적이거나 유명한 사람일 때 관찰학습 효과가 더 커지는 경향이 있습니다.","일정 시간을 기준으로 강화가 주어지나 그 시간 간격이 평균시간을 전후 로 불규칙하게 변한다":"변동간격강화계획은 강화 기준 시간이 평균 주변에서 불규칙하게 달라지는 방식입니다.","자극과 반응 간 연합은 연습만으로도 강화된다":"되풀이 연습만으로도 자극과 반응의 연결이 단단해진다는 내용으로 연습의 법칙에 해당합니다.","자극과의 연결 강도가 높아진다":"만족스러운 결과를 얻은 반응은 그 자극과의 연결이 더 세져 다시 나오기 쉬워집니다.","자아실현 욕구는 모든 인간에게 내재되어 있다":"자아실현 욕구는 특정인이 아니라 누구에게나 본래 있습니다.","자아실현 욕구는 완전히 만족되지 않는다":"자아실현 욕구는 채워도 계속 이어져 결핍 욕구와 달리 끝나지 않습니다.","자전거 타기, 수영하기, 타이핑하기 등이 있다":"절차기억은 방법을 아는 기억이라 자전거 타기나 타이핑 같은 기능으로 나타납니다.","정보가 다른 정보와 섞이거나 다른 정보에 의해 대체되기 때문에 망각이 일어난다":"간섭이론은 다른 정보가 끼어들어 원래 정보를 밀어내기 때문에 잊는다고 봅니다.","정보는 시각적 부호와 언어적 부호로 입력된다":"정보가 이미지 형태와 말 형태, 두 가지 부호로 기억에 들어갑니다.","정보를 조직하고 다른 정보들과 관련짓는 기억체계의 요소이다":"작업기억은 정보를 정리하고 다른 정보와 연결하는 처리 기능을 맡습니다.","정적 강화를 받을 때 분비되는 신경전달 물질이며 강화중추와 관련 있는 호르몬이다":"도파민은 보상을 받을 때 나오는 물질로 강화중추와 관련이 있습니다.","지식은 혼자 발견하기보다 타인과의 상호작용을 통해 전수된다":"지식은 개인이 홀로 찾기보다 다른 사람과 주고받으며 전해진다고 봅니다.","처벌 받는 행동은 분명하고 구체적인 용어로 제시되어야 한다":"어떤 행동이 문제인지 구체적으로 알려 줘야 처벌받는 이유를 정확히 이해합니다.","처벌받는 행동을 대신할 바람직한 행동에 대한 학습 기회를 제공해야 한다":"처벌만 하면 멈춰야 할 행동만 알게 되므로 대신 할 바람직한 행동을 배울 기회가 필요합니다.","처벌 받는 행동이 받아들여질 수 없는 이유에 대해 설명해 주어야 한다":"이유를 설명해 주면 처벌이 변덕이 아니라 규칙에 따른 것임을 알게 됩니다.","처벌은 일관성이 있어야 한다":"같은 행동에는 늘 같은 처벌이 따라야 행동과 결과의 관계가 흐려지지 않습니다.","처벌 전 사전 경고를 하는 것이 효과적이다":"처벌하기 전에 미리 경고하면 행동과 결과의 관계를 알게 되어 효과가 커집니다.","출생 후 2∼3년에 걸쳐 이루어진다":"국소화는 기능별 담당 영역이 정해지는 과정으로 출생 후 2∼3년에 걸쳐 진행됩니다.","타인의 행동을 마치 자신의 행동을 보는 것처럼 느끼게 하는 뉴런":"거울뉴런이 있어 남이 하는 행동을 볼 때도 자기가 하는 것처럼 느낄 수 있습니다.","태도의 변화는 학습의 영역에 포함된다":"학습은 지식과 기술뿐 아니라 태도가 바뀌는 것까지 포괄합니다.","통찰로 얻은 원리는 구조적으로 유사한 문제에 쉽게 적용할 수 있다":"구조가 닮은 다른 문제에도 깨달은 원리를 그대로 옮겨 쓸 수 있습니다.","통찰로 얻은 해결책에 기초한 수행은 대개 부드럽고 오류가 없다":"해결책을 깨달은 뒤의 수행은 매끄럽고 실수가 거의 없습니다.","통찰로 얻은 해결책은 상당한 시간 동안 유지된다":"통찰로 얻은 해결책은 쉽게 잊히지 않고 오래 남습니다.","통합된 조절(integrated regulation)보다":"통합된 조절은 내적 조절보다 자율성이 낮은 쪽에 놓이는 조절 유형입니다.","피로는 부적 추동 상태이기 때문에 피로 상태에서는 반응하지 않는 것이 강화적인 속성을 갖는다":"각성이론에서 피로는 불쾌한 추동이므로 반응을 멈추는 것 자체가 그 불쾌를 줄여 강화가 됩니다.","하위 단계의 욕구가 충족된 다음에 상위 단계 욕구가 나타난다":"욕구위계는 아래 단계가 채워져야 위 단계 욕구가 나타나는 순서를 이룹니다.","학습과제 사이에 유사성의 정도가 높을수록 전이가 많이 일어 난다":"동일요소설은 두 과제에 같은 요소가 많을수록 전이가 커진다고 봅니다.","학습된 것이 행동으로 드러나지 않을 수 있다":"배운 내용이 있어도 드러낼 기회나 동기가 없으면 행동으로 나타나지 않을 수 있습니다.","학습된 반응은 이미 형성된 방향으로 일어나기 쉽다":"한번 굳어진 반응은 같은 방향으로 되풀이되기 쉽다는 경향을 가리킵니다.","학습은 경험을 통하여 이루어진다":"학습은 타고난 성숙이 아니라 경험으로 생기는 변화여서 경험이 학습의 조건이 됩니다.","학습은 통찰적이라기보다 점진적이다":"시행착오설은 갑자기 깨닫는 방식보다 조금씩 쌓이며 학습이 진행된다고 봅니다.","학습의 결과는 인지도(cognitive map)로 만들어진다":"학습 결과는 환경의 공간 구조를 머릿속에 그린 지도, 곧 인지도로 저장됩니다.","학습자는 통찰을 통한 문제해결의 원리를 구조적으로 유사한 문제에 쉽게 적용할 수 있다":"원리를 이해해서 얻은 해결이기에 닮은 구조의 문제로 전이가 쉽게 일어납니다.","학습활동시의 맥락과 전이 상황의 맥락이 유사할 때 일어난다":"근접 전이는 배운 상황과 적용 상황이 비슷할 때 일어납니다.","한 형태의 추론에서 다른 형태로의 추론으로 전이하는 핵심요인은 물리적 환경, 성숙, 사회적 영향, 평형이다":"추론의 전이를 일으키는 요인으로 물리적 환경, 성숙, 사회적 영향, 평형 네 가지가 꼽힙니다.","행동과 의식은 환경과의 관계에서 생성되고 소멸하는 과정이다":"행동과 의식은 고정된 실체가 아니라 환경과 맺는 관계 속에서 생겼다가 사라집니다.","행동과 처벌 간 시간 간격이 길수록 처벌의 효과는 떨어진다":"행동과 처벌 사이가 벌어질수록 둘의 연결이 약해져 처벌 효과가 줄어듭니다.","행동 변화는 학습 경험 후에 즉시 일어나지 않아도 된다":"학습 경험을 했더라도 행동의 변화는 한참 뒤에 나타날 수 있습니다.","활동에 완벽하게 몰두하는 상태를 말한다":"몰입은 하고 있는 활동에 온전히 빠져드는 상태입니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
